import {
  Component,
  OnDestroy,
  ViewChild,
  ViewChildren,
  QueryList,
  ViewEncapsulation,
  AfterViewInit,
} from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { ENV } from '@app/env';
import { ModalController, NavController } from '@ionic/angular';
import { TranslateService } from '@ngx-translate/core';
import { NgxPubSubService } from '@pscoped/ngx-pub-sub';
import { MagAppDialogComponent } from '@rsApp/components/mag-app-dialog/mag-app-dialog';
import { MagModalConfirmComponent } from '@rsApp/components/mag-confirm-modal/mag-modal-confirm';
import { AuthService } from '@rsApp/modules/auth-v2/providers/auth-v2.service';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
// import { CmsService } from '@rsApp/modules/dashboard/providers/cms.service';
import { CurrentStore } from '@rsApp/modules/store/store.module';
import { enumTrackAction } from '@rsApp/modules/utils/enum/enum';
import { AppSettings } from '@rsApp/modules/utils/providers/app-setting';
import { IExtrasStateData } from '@rsApp/modules/utils/providers/navExtrasStateResolve.service';
import { RSTracker } from '@rsApp/modules/utils/providers/rs-tracker.service';
import { Utils } from '@rsApp/modules/utils/providers/utils';
import { CacheService } from 'ionic-cache';
import _ from 'lodash';
import { Subscription } from 'rxjs';
import { WidgetLayoutComponent } from '@rsApp/modules/utils/components/widget-layout/widget-layout.component';
import { HomeSkeletonComponent } from '@rsApp/modules/utils/components/skeletons/home/home-skeleton.component';
import { PerformanceLoggerService } from '@rsApp/modules/utils/providers/performance-logger.service';
import { WidgetPrerenderService } from '@rsApp/modules/utils/providers/widget-prerender.service';

@Component({
  selector: 'home-page',
  templateUrl: 'home.html',
  styleUrls: ['home.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class HomePageComponent implements OnDestroy, AfterViewInit {
  public currentUser: any;
  public currentStore: any;

  innerHTML = '';
  receiveTextMessage = false;
  receiveEmail = false;

  public subscriptions: Array<Subscription> = [];
  @ViewChild('slides', { static: true }) slides: any;
  @ViewChildren(WidgetLayoutComponent) widgetLayouts!: QueryList<WidgetLayoutComponent>;
  @ViewChild(HomeSkeletonComponent) homeSkeleton!: HomeSkeletonComponent;

  private skeletonHidden = false;
  slideOpts = {
    initialSlide: 1,
    speed: 400,
    autoplay: {
      delay: 5000,
    },
  };
  returnRoute: string;
  public displayOnlineOrderBanner: boolean;

  private eventSubscription: Subscription;
  @ViewChild('dialogThanksModal') dialogThanksModal!: MagAppDialogComponent;
  @ViewChild('dialogCheckPhoneModal') dialogCheckPhoneModal!: MagAppDialogComponent;

  constructor(
    public utils: Utils,
    public auth: AuthService,
    public cStore: CurrentStore,
    public modalCtrl: ModalController,
    public router: Router,
    public route: ActivatedRoute,
    public cache: CacheService,
    public navCtrl: NavController,
    public appSettings: AppSettings,
    public tracker: RSTracker,
    public events: NgxPubSubService,
    public cre: Credential,
    public translate: TranslateService,
    private perfLogger: PerformanceLoggerService,
    private widgetPrerenderService: WidgetPrerenderService
  ) {
    this.perfLogger.mark('HOME_COMPONENT_CONSTRUCTOR');
    const params = this.route.snapshot.paramMap;
    this.returnRoute = params.get('returnRoute');
    this.subscriptions.push(
      this.cStore.storeState().subscribe((store) => {
        this.currentStore = store;
      })
    );

    const { receiveEmail, receiveTextMessage } = (<IExtrasStateData>this.route.snapshot.data).extrasStateResolver;
    this.receiveEmail = receiveEmail ?? false;
    this.receiveTextMessage = receiveTextMessage ?? false;

    // Reset state after get it
    history.replaceState({}, '', this.router.url);
  }

  async ionViewWillEnter() {
    this.perfLogger.mark('HOME_VIEW_WILL_ENTER');
    this.trackPage();
    this.events.publishEvent('reload-timeslot');
    this.events.publishEvent('reload-widget');
    this.displayOnlineOrderBanner = ENV.OnlineOrderEnabled;
  }

  async doRefresh(event: any) {
    this.perfLogger.log('🔄 Pull to refresh triggered');

    try {
      // Show skeleton during refresh
      if (this.homeSkeleton) {
        this.skeletonHidden = false;
        this.homeSkeleton.show();
        this.perfLogger.log('💀 Skeleton shown for refresh');
      }

      // Reload widgets by publishing reload event
      this.events.publishEvent('reload-widget');

      // Reload timeslot data
      this.events.publishEvent('reload-timeslot');

      event.target.complete();
      // Refresh all widget-layout components
      const widgets = this.widgetLayouts.toArray();
      if (widgets.length > 0) {
        this.perfLogger.log(`🔄 Refreshing ${widgets.length} widget-layout components`);

        // Set up a promise to wait for the first widget to be ready
        const firstWidgetReady = new Promise<void>((resolve) => {
          let resolved = false;
          widgets.forEach((widget) => {
            widget.widgetReady.subscribe(() => {
              if (!resolved) {
                resolved = true;
                resolve();
              }
            });
          });

          // Fallback: resolve after 3 seconds if no widget emits
          setTimeout(() => {
            if (!resolved) {
              resolved = true;
              resolve();
            }
          }, 3000);
        });

        // Start refreshing all widgets
        const refreshPromises = widgets.map((widget) => widget.refresh());

        // Wait for refresh to complete and first widget to be ready
        await Promise.all([...refreshPromises, firstWidgetReady]);

        this.perfLogger.log('✅ All widgets refreshed');
      }

      // Hide skeleton after widgets are ready
      if (this.homeSkeleton && !this.skeletonHidden) {
        this.homeSkeleton.hide();
        this.skeletonHidden = true;
        this.perfLogger.log('💀 Skeleton hidden after refresh');
      }

      // Complete the refresh
      event.target.complete();
      this.perfLogger.log('✅ Pull to refresh completed');
    } catch (error) {
      console.error('Error during refresh:', error);
      this.perfLogger.log('❌ Error during refresh', error);

      // Hide skeleton even on error
      if (this.homeSkeleton && !this.skeletonHidden) {
        this.homeSkeleton.hide();
        this.skeletonHidden = true;
      }
    }
  }

  ngAfterViewInit() {
    this.perfLogger.mark('HOME_AFTER_VIEW_INIT');
    // Wait for widget layouts to be available
    setTimeout(() => {
      this.setupWidgetTracking();

      // Also listen for changes in the widget list
      this.widgetLayouts.changes.subscribe(() => {
        this.setupWidgetTracking();
      });
    }, 150);
  }

  setupWidgetTracking() {
    const widgets = this.widgetLayouts.toArray();
    this.perfLogger.log(`🔍 Found ${widgets.length} widget-layout components`);

    if (widgets.length === 0) {
      // No widgets, hide skeleton immediately
      if (this.homeSkeleton && !this.skeletonHidden) {
        this.perfLogger.log('⚠️ No widgets found, hiding skeleton immediately');
        this.homeSkeleton.hide();
        this.skeletonHidden = true;
      }
      return;
    }

    // Subscribe to the first widget's ready event
    widgets.forEach((widget, index) => {
      widget.widgetReady.subscribe(() => {
        this.perfLogger.log(`✅ Widget ${index + 1} ready`);
        // Hide skeleton as soon as first widget is ready
        if (this.homeSkeleton && !this.skeletonHidden) {
          setTimeout(() => {
            this.perfLogger.mark('FIRST_WIDGET_READY');
            this.perfLogger.log('🎉 Hiding skeleton - first widget loaded');
            this.homeSkeleton.hide();
            this.skeletonHidden = true;
          }, 500);
        }
      });
    });
  }

  async ionViewDidEnter() {
    this.perfLogger.mark('HOME_VIEW_DID_ENTER');
    this.perfLogger.printSummary('HOME_VIEW_DID_ENTER');
    if (this.receiveTextMessage) {
      this.dialogCheckPhoneModal.openDialog();
    } else if (this.receiveEmail) {
      this.dialogThanksModal.openDialog();
    }

    if (this.currentUser) {
      customElements.whenDefined('dxp-notification-icon').then(() => {
        this.innerHTML = '<dxp-notification-icon theme="dark" path="/notification"></dxp-notification-icon>';
      });
    }

    this.widgetPrerenderService.clearPrerenderStencilComponent();
  }
  ngOnDestroy() {
    _.each(this.subscriptions, (s: Subscription) => {
      s.unsubscribe();
    });

    if (this.eventSubscription) {
      this.eventSubscription.unsubscribe();
    }
  }

  onCloseModalThanksSubscribing() {
    this.receiveEmail = false;
    this.dialogThanksModal.closeDialog();
  }

  onCloseModalCheckPhone() {
    this.receiveTextMessage = false;
    this.dialogCheckPhoneModal.closeDialog();
  }

  onNavigateWeeklyAds() {
    this.onCloseModalThanksSubscribing();
    setTimeout(() => {
      this.router.navigate(['/tabs/weekly-ad']);
    }, 0);
  }

  chooseStorePage() {
    const cri = {
      keyword: '',
      size: 3,
    };
    this.cache.saveItem('store-search-params', cri);
    this.cache.saveItem('store-back', { route: ['/tabs/home'], key: 'selected-store' }, 'store');
    // Using navigateRoot for refresh home page data
    this.navCtrl.navigateRoot([
      '/store/near',
      {
        type: 'chooseStore',
        returnRoute: 'tabs/home',
      },
    ]);
  }

  goSlider(slider) {
    if (slider.SliderType === 'EndCap') {
      this.router.navigate([
        '/tabs/products/product-encap',
        {
          sliderId: slider.Id,
          sliderTitle: slider.Title,
        },
      ]);
    } else {
      if (slider.Link.search('app://') !== -1) {
        const pageName = _.replace(slider.Link, 'app://', '');
        this.router.navigateByUrl(pageName);
      } else if (slider.Link.search(ENV.URLSCHEME) !== -1) {
        // deprecate
        const pageName = _.replace(slider.Link, ENV.URLSCHEME + '//', '');
        this.router.navigate([pageName]);
      } else {
        if (slider.Link && this.utils.validURL(slider.Link)) {
          if (this.currentUser) {
            if (slider.LinkOut) {
              // window.open(slider.Link, '_system', '');
              this.utils.openInSystem(slider.Link);
            } else {
              this.utils.openInaAppBrowser(slider.Link);
            }
          } else {
            if (slider.SignOutLinkOut) {
              // window.open(slider.Link, '_system', '');
              this.utils.openInSystem(slider.SignOutLink);
            } else {
              this.utils.openInaAppBrowser(slider.SignOutLink);
            }
          }
        }
      }
    }
  }
  onIonSlidesDidLoad(slider) {
    slider.startAutoplay();
  }

  trackPage() {
    this.events.publishEvent(enumTrackAction.OnChangeSystemService, { systemServiceName: this.currentStore?.ShopPath });
  }

  viewMoreStore() {
    if (this.returnRoute) {
      this.router.navigate(['/store/find', { router: this.returnRoute }]);
    } else {
      this.router.navigate(['/store/find']);
    }
  }

  public getPageName() {
    return 'HomePage';
  }

  async openSubscriptionNotAppliedModal() {
    const modal = await this.modalCtrl.create({
      component: MagModalConfirmComponent,
      componentProps: {
        title: this.translate.instant('subscriptions.subscriptionNotApplied.title'),
        description: this.translate.instant('subscriptions.subscriptionNotApplied.content'),
        confirmTitle: this.translate.instant('subscriptions.subscriptionNotApplied.primaryButtonText'),
        cancelTitle: this.translate.instant('subscriptions.subscriptionNotApplied.secondaryButtonText'),
      },
      cssClass: 'mag-confirm-modal',
    });

    modal.onDidDismiss().then(async (result) => {
      if (result.data) {
        this.router.navigate(['/tabs/my-account'], {
          state: {
            openPreferencesOnInit: true,
          },
        });
      }
    });

    await modal.present();
  }
}
